'use strict';
const CONTACT_EMAIL='minjjjhhh@gmail.com';
const main=document.querySelector('main');
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const finePointer=window.matchMedia('(hover:hover) and (pointer:fine)');
const projects=[{name:'Northwind',year:'2026'},{name:'Luma',year:'2025'},{name:'Cedar & Stone',year:'2025'},{name:'Meridian',year:'2026'}];
const services=[['Branding & Visual Identity',['브랜딩','브랜드 전략','키비주얼','브랜드 로고','타이포그래피'],'브랜드의 방향성을 설정하고 시각적 정체성을 만드는 분야'],['UI/UX Design',['사용자 리서치','정보 구조(IA)','UI 디자인','와이어프레임','프로토타입'],'사용자의 요구와 서비스 목적을 고려해 디지털 인터페이스를 설계하는 분야'],['Website Design',['웹 레이아웃','랜딩페이지','웹 UI','반응형 디자인'],'웹사이트의 정보와 시각 요소를 목적에 맞게 구성하는 분야'],['Visual & AI Design',['그래픽 디자인','아트 디렉션','무드보드','AI 이미지 제작'],'콘셉트를 이미지와 그래픽으로 구체화하는 분야']];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const graphemes=s=>typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('ko',{granularity:'grapheme'}).segment(s)].map(s=>s.segment):Array.from(s);
function media(label,extra=''){return `<div class="project-visual ${extra}"><span class="placeholder-label">${escapeHTML(label)}</span></div>`;}
function projectCard(p,i,work=false){const name=work?`프로젝트명0${i+1}`:p.name;const href=work?'#/case':'#/work';return `<a class="project-card reveal" href="${href}" data-project="${i}" aria-label="${escapeHTML(name)} ${work?'프로젝트 상세 보기':'Work 페이지 보기'}" style="--delay:${(i%2)*.1}s"><div class="project-visual" data-cursor="${work?'View Project ↗':'View Work ↗'}"><span class="placeholder-label">PROJECT VISUAL</span><div class="marquee" aria-hidden="true"><div class="marquee-track">${Array.from({length:8},()=>`<span>${escapeHTML(name)} · ${p.year} ·</span>`).join('')}</div></div></div><div class="project-info"><h3>${escapeHTML(name)}</h3><div class="project-meta"><span>디자인분야</span><span>프로젝트 유형</span><span>디자인툴</span><span>${p.year} · 프로젝트 상세 보기 ↗</span></div></div></a>`;}
function contact(){return `<section class="section contact-section" id="contact" aria-labelledby="contact-title"><div class="section-heading reveal"><h2 class="contact-title" id="contact-title"><strong>CONTACT / </strong>디자인을 통해 더 나은 경험을 고민합니다.</h2><p>브랜드와 디지털 경험을 고민하며, 더 나은 디자인을 위해 꾸준히 배우고 있습니다.</p></div><div class="contact-split"><div class="contact-profile reveal"><div class="contact-portrait"><img src="assets/contact-portrait.svg" width="172.387" height="145.566" alt="프로필 이미지 영역"><div class="socials"><button type="button" data-info="instagram" aria-label="Instagram 안내"><img src="assets/instagram.svg" width="22.5184" height="22.5184" alt=""></button><button type="button" data-info="profile" aria-label="프로필 안내"><img src="assets/user.svg" width="27.0221" height="27.0221" alt=""></button><button type="button" data-info="youtube" aria-label="YouTube 안내"><img src="assets/youtube.svg" width="27.0221" height="27.0221" alt=""></button></div></div><div class="contact-details"><a class="roll" href="mailto:${CONTACT_EMAIL}">${CONTACT_EMAIL}</a></div></div><form class="contact-form reveal" novalidate><div class="field"><label for="name">Name</label><input id="name" name="name" placeholder="입력 영역" autocomplete="name" required maxlength="100" aria-describedby="name-error"><p class="field-error" id="name-error"></p></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" placeholder="입력 영역" autocomplete="email" required maxlength="254" aria-describedby="email-error"><p class="field-error" id="email-error"></p></div><div class="field"><label for="service">Service · 서비스 선택 ▾</label><select id="service" name="service" required aria-describedby="service-error"><option value="">서비스 선택</option>${services.map(s=>`<option>${escapeHTML(s[0])}</option>`).join('')}<option>Other</option></select><p class="field-error" id="service-error"></p></div><div class="field"><label for="message">Message</label><textarea id="message" name="message" placeholder="입력 영역" required maxlength="4000" aria-describedby="message-error"></textarea><p class="field-error" id="message-error"></p></div><button class="cta roll" type="submit">Send Message ↗</button><p class="form-note">작성한 내용으로 메일 앱이 열립니다. 메일 앱에서 전송을 완료해 주세요.</p><p class="form-status" role="status" aria-live="polite"></p></form></div></section>`;}
function footer(){return `<footer class="footer"><a class="footer-name reveal" href="#home" aria-label="홈으로">Jihye Min<small>ⓜ</small></a><div class="footer-bottom"><p>Designed in Framer By <strong>MinJihye</strong></p><p><button type="button" class="roll" data-info="privacy">Privacy Policy</button> · <button type="button" class="roll" data-info="terms">Terms & Conditions</button></p><p><strong>© 2026</strong> All rights reserved</p></div></footer>`;}
function landing(){return `<section class="hero" id="home" aria-label="디자이너 소개"><div class="hero-inner"><h1 class="hero-name" aria-label="Jihye Minⓜ">${graphemes('Jihye Minⓜ').map((c,i)=>`<span class="char-wrap" aria-hidden="true"><span class="hero-char" style="--i:${i}">${c===' '?'&nbsp;':escapeHTML(c)}</span></span>`).join('')}</h1><p class="hero-description">복잡한 문제를 단순하고 직관적인<br>디지털 경험으로 만듭니다.<br>복잡한 문제를 단순하고 직관적인<br>디지털 경험으로 만듭니다.</p></div><p class="hero-role">BX & Brand Designer</p></section><section class="section" id="work" aria-labelledby="work-title"><a class="section-heading reveal" href="#/work"><h2 id="work-title">FEATURED PROJECTS</h2><p>프로젝트 간단 설명 : 첫 화면에서 시각적 작업 증거를 보여주고 상세 사례로 진입</p></a><div class="project-grid">${projects.map((p,i)=>projectCard(p,i)).join('')}</div><div class="cta-row reveal"><a class="cta roll upper view-all" href="#/work">View All Projects ↗</a></div></section><section class="section" id="services" aria-labelledby="services-title"><div class="section-heading reveal"><h2 id="services-title">What I Do</h2><p>UI·브랜딩부터 웹·모바일 제품의 전체 디자인까지</p></div><div class="service-grid">${services.map(([title,tags,desc],i)=>`<article class="service-card reveal" style="--delay:${i%2*.1}s">${media('Design VISUAL')}<h3>${escapeHTML(title)}</h3><div class="service-detail"><div class="tags">${tags.map(t=>`<span class="tag"><img src="assets/check.svg" width="24" height="24" alt="">${escapeHTML(t)}</span>`).join('')}</div><p>${escapeHTML(desc)}</p></div></article>`).join('')}</div></section><section class="section" id="about" aria-labelledby="about-title"><h2 class="reveal" id="about-title">About me</h2><p class="about-intro read-text">디자인과 기술의 교차점에서,보기 좋고 쓰기 편한 인터페이스를 만듭니다.<br>디자인과 기술을 연결해, 보기 좋은 디자인을 넘어 사용하기 편리하고 직관적인 경험을 만듭니다.</p><div class="about-split"><div class="portrait reveal"><img src="assets/portrait.svg" width="136.583" height="115.333" alt="프로필 이미지 영역"></div><div class="about-statement"><div class="reveal"><h3>브랜드의 본질을 경험으로 디자인합니다.</h3><p>브랜드가 전하는 인상부터 고객이 마주하는 순간까지 세심하게 고민합니다.</p></div><a class="cta roll upper reveal" href="#contact">Get in Touch ↗</a></div></div></section>${contact()}${footer()}`;}
function work(){return `<section class="section" id="work"><div class="section-heading reveal"><h1 class="work-title">Selected Work</h1><p class="work-description">브랜드부터 디지털까지, 다양한 디자인 프로젝트를 소개합니다.</p></div><p class="work-year reveal">© 2026</p><div class="filters reveal" role="group" aria-label="프로젝트 카테고리">${['All','Branding','UI/UX Design','Website Design','Strategy & Research'].map((s,i)=>`<button type="button" class="roll" data-filter="${escapeHTML(s)}" aria-pressed="${i===0}">${escapeHTML(s)}</button>`).join('')}</div><div class="project-grid">${projects.map((p,i)=>projectCard(p,i,true)).join('')}</div><p class="empty-state" hidden>선택한 분야의 프로젝트가 아직 등록되지 않았습니다.</p></section>${contact()}${footer()}`;}
function caseStudy(){return `<section class="section"><h1 class="work-title reveal">프로젝트명01-MOVERA</h1><p class="work-description reveal">프로젝트의 목표와 핵심 작업을 한 문장으로 소개 → 브랜드 콘셉트와 네이밍부터 시각적 방향성까지 기획한 브랜드 프로젝트</p><dl class="detail-meta reveal">${[['Project Type','Branding / UI/UX'],['Role','실제 담당 업무'],['Duration','실제 진행 기간'],['Year','제작 연도']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="reveal">${media('PROJECT HERO IMAGE','detail-hero')}</div></section><section class="section"><h2 class="reveal">01 / The problem</h2><p class="detail-body read-text">프로젝트에서 해결하고자 한 문제는 무엇인가요?</p><p class="reveal">문제 상황과 리서치 결과, 핵심 인사이트를 소개하는 영역입니다.</p><div class="reveal">${media('문제와 기존 경험을 보여주는 프로젝트 이미지','detail-image')}</div></section><section class="section"><h2 class="reveal">02 / The solution</h2><p class="detail-body read-text">문제를 해결하기 위해 어떤 방향을 선택했나요?</p><p class="reveal">전략과 디자인 결과물, 주요 시각 자료를 배치합니다.</p><div class="detail-pair"><div class="reveal">${media('SOLUTION VISUAL 01')}</div><div class="reveal">${media('SOLUTION VISUAL 02')}</div></div><div class="reveal">${media('PROJECT GALLERY / FULL WIDTH','detail-image')}</div></section>${contact()}${footer()}`;}
let currentPage='',routeBusy=false,observer=null,reading=[];
function pageFromHash(hash){return hash.startsWith('#/work')?'work':hash.startsWith('#/case')?'case':'home';}
function makeRolling(root=document){root.querySelectorAll('.roll:not([data-roll-ready])').forEach(el=>{const value=el.textContent.trim();el.dataset.rollReady='true';if(!el.hasAttribute('aria-label'))el.setAttribute('aria-label',value);const outer=document.createElement('span');outer.className='roll-text';outer.setAttribute('aria-hidden','true');let groups=[value];if(el.matches('[data-filter]')){outer.classList.add('multiline');if(value==='UI/UX Design')groups=['UI/UX','Design'];if(value==='Website Design')groups=['Website','Design'];if(value==='Strategy & Research')groups=['Strategy &','Research'];}let idx=0;for(const group of groups){const line=document.createElement('span');line.className='roll-line';graphemes(group).forEach(c=>{const letter=document.createElement('span');letter.className='roll-letter';letter.style.setProperty('--i',idx++);for(const cls of ['roll-front','roll-back']){const span=document.createElement('span');span.className=cls;span.textContent=c===' '?'\u00a0':c;letter.append(span);}line.append(letter);});outer.append(line);}el.replaceChildren(outer);});}
function splitReadText(el){el.setAttribute('aria-label',el.textContent);const fragment=document.createDocumentFragment();for(const node of [...el.childNodes]){if(node.nodeType===Node.ELEMENT_NODE){fragment.append(node.cloneNode(true));continue;}for(const word of (node.textContent||'').split(/(\s+)/)){if(!word)continue;if(/^\s+$/.test(word)){fragment.append(document.createTextNode(word));continue;}const group=document.createElement('span');group.className='read-word';group.setAttribute('aria-hidden','true');for(const char of graphemes(word)){const c=document.createElement('span');c.className='read-char';c.textContent=char;group.append(c);}fragment.append(group);}}el.replaceChildren(fragment);return {el,chars:[...el.querySelectorAll('.read-char')]};}
function initView(){makeRolling();observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}},{threshold:.08,rootMargin:'0px 0px -5% 0px'});main.querySelectorAll('.reveal').forEach(el=>observer.observe(el));reading=[...main.querySelectorAll('.read-text')].map(splitReadText);initForm();updateScroll();document.title=currentPage==='work'?'Selected Work — Jihye Min':currentPage==='case'?'MOVERA — Jihye Min':'Jihye Min — BX & Brand Designer';}
function render(page){currentPage=page;main.innerHTML=page==='work'?work():page==='case'?caseStudy():landing();initView();}
async function go(hash,replace=false){if(routeBusy)return;const targetPage=pageFromHash(hash);closeMenu();cursor.classList.remove('visible');if(targetPage!==currentPage){routeBusy=true;const cover=document.querySelector('.transition-cover');if(!reduceMotion.matches){cover.className='transition-cover enter';await new Promise(r=>setTimeout(r,280));}render(targetPage);window.scrollTo({top:0,behavior:'instant'});if(!reduceMotion.matches){await new Promise(r=>requestAnimationFrame(r));cover.className='transition-cover exit';setTimeout(()=>{cover.className='transition-cover';},650);}routeBusy=false;main.focus({preventScroll:true});}if(replace)history.replaceState(null,'',hash);else if(location.hash!==hash)history.pushState(null,'',hash);if(targetPage==='home'&&['#home','#about','#contact','#work'].includes(hash)){const target=main.querySelector(hash);target?.scrollIntoView({behavior:reduceMotion.matches?'instant':'smooth',block:'start'});}else if(hash==='#contact'){main.querySelector('#contact')?.scrollIntoView({behavior:reduceMotion.matches?'instant':'smooth'});}}
const toggle=document.querySelector('.menu-toggle'),mobileMenu=document.querySelector('.mobile-menu');
function closeMenu(){document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','메뉴 열기');mobileMenu.inert=true;}
toggle.addEventListener('click',()=>{const open=!document.body.classList.contains('menu-open');document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');mobileMenu.inert=!open;if(open)setTimeout(()=>mobileMenu.querySelector('a').focus(),150);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();toggle.focus();}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const links=[toggle,...mobileMenu.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===links[0]){e.preventDefault();links.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===links.at(-1)){e.preventDefault();links[0].focus();}}});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link&&link.getAttribute('href')!=='#main'){e.preventDefault();let hash=link.getAttribute('href');if(hash==='#contact'&&currentPage!=='home'){closeMenu();main.querySelector('#contact')?.scrollIntoView({behavior:reduceMotion.matches?'instant':'smooth'});return;}go(hash);}const filter=e.target.closest('[data-filter]');if(filter){main.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));const showAll=filter.dataset.filter==='All';main.querySelectorAll('[data-project]').forEach(c=>{c.hidden=!showAll;c.classList.add('in-view');});main.querySelector('.empty-state').hidden=showAll;}const info=e.target.closest('[data-info]');if(info)showInfo(info.dataset.info);});
window.addEventListener('popstate',()=>go(location.hash||'#home',true));
window.addEventListener('hashchange',()=>go(location.hash||'#home',true));
const dialog=document.querySelector('dialog');dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function showInfo(type){const messages={privacy:['Privacy Policy','문의 폼에서 작성한 내용은 이 사이트의 서버로 전송되지 않습니다. Send Message를 선택하면 사용자의 메일 앱으로 내용이 전달되며, 실제 전송은 메일 앱에서 완료됩니다. 별도의 분석 쿠키는 사용하지 않습니다.'],terms:['Terms & Conditions','이 포트폴리오의 디자인과 콘텐츠를 무단으로 재배포하지 말아 주세요. 프로젝트 비주얼 및 일부 문구는 피그마 와이어프레임의 자리표시자입니다.'],instagram:['Instagram','Instagram 계정 링크를 준비하고 있습니다. 문의는 '+CONTACT_EMAIL+'으로 보내 주세요.'],profile:['Profile','프로필 링크를 준비하고 있습니다. 문의는 '+CONTACT_EMAIL+'으로 보내 주세요.'],youtube:['YouTube','YouTube 채널 링크를 준비하고 있습니다. 문의는 '+CONTACT_EMAIL+'으로 보내 주세요.']};const [title,body]=messages[type]||messages.profile;dialog.querySelector('h2').textContent=title;dialog.querySelector('p').textContent=body;dialog.showModal();}
function initForm(){const form=main.querySelector('form');if(!form)return;const fields=[...form.querySelectorAll('input,select,textarea')];function validate(el){let error='';if(!el.value.trim())error=el.name==='service'?'서비스를 선택해 주세요.':'내용을 입력해 주세요.';else if(el.type==='email'&&!el.validity.valid)error='올바른 이메일 주소를 입력해 주세요.';el.setAttribute('aria-invalid',String(!!error));form.querySelector('#'+el.id+'-error').textContent=error;return !error;}fields.forEach(el=>{el.addEventListener('blur',()=>validate(el));el.addEventListener('input',()=>{if(el.getAttribute('aria-invalid')==='true')validate(el);form.querySelector('.form-status').textContent='';});});form.addEventListener('submit',e=>{e.preventDefault();let valid=true;fields.forEach(el=>{if(!validate(el))valid=false;});if(!valid){form.querySelector('[aria-invalid=true]')?.focus();return;}const data=new FormData(form);const subject=`[디자인 문의] ${data.get('service')} — ${data.get('name')}`;const body=`이름: ${data.get('name')}\n이메일: ${data.get('email')}\n서비스: ${data.get('service')}\n\n${data.get('message')}`;const href=`mailto:${CONTACT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;const mail=document.createElement('a');mail.href=href;mail.hidden=true;document.body.append(mail);mail.click();mail.remove();form.querySelector('.form-status').textContent='메일 작성 창을 열었습니다. 메일 앱에서 전송을 완료해 주세요. 창이 열리지 않았다면 '+CONTACT_EMAIL+'으로 직접 보내 주세요.';});}
let pendingScroll=false;function updateScroll(){pendingScroll=false;document.querySelector('.header').classList.toggle('is-scrolled',scrollY>20);for(const {el,chars}of reading){const rect=el.getBoundingClientRect();const progress=reduceMotion.matches?1:Math.max(0,Math.min(1,(innerHeight*.92-rect.top)/(innerHeight*.42+rect.height)));chars.forEach((c,i)=>c.classList.toggle('is-lit',i/chars.length<progress));}}
addEventListener('scroll',()=>{if(!pendingScroll){pendingScroll=true;requestAnimationFrame(updateScroll);}},{passive:true});addEventListener('resize',updateScroll);
const cursor=document.querySelector('.project-cursor');let pointer={x:0,y:0},cursorPoint={x:0,y:0},cursorRAF=0;
function followCursor(){cursorPoint.x+=(pointer.x-cursorPoint.x)*.2;cursorPoint.y+=(pointer.y-cursorPoint.y)*.2;cursor.style.translate=`${cursorPoint.x}px ${cursorPoint.y}px`;if(cursor.classList.contains('visible'))cursorRAF=requestAnimationFrame(followCursor);else cursorRAF=0;}
document.addEventListener('pointermove',e=>{if(!finePointer.matches||reduceMotion.matches)return;pointer={x:e.clientX,y:e.clientY};const target=e.target.closest('[data-cursor]');if(target){cursor.querySelector('span').textContent=target.dataset.cursor;if(!cursor.classList.contains('visible')){cursorPoint={...pointer};cursor.classList.add('visible');}if(!cursorRAF)followCursor();}else cursor.classList.remove('visible');},{passive:true});document.addEventListener('pointerleave',()=>cursor.classList.remove('visible'));
render(pageFromHash(location.hash));document.fonts.ready.then(()=>{updateScroll();if(['#about','#contact'].includes(location.hash))main.querySelector(location.hash)?.scrollIntoView({behavior:'instant'});});
